import {getDictList} from "@/api/dict";
import {getList, remove} from "@/api/endpoint/port";
import {mapGetters, mapState} from "vuex";
import PortResAddEdit from "./components/port/addedit.vue";
import PortDetial from "./components/port/detail.vue";

export default {
  components: {PortResAddEdit, PortDetial},
  data() {
    return {
      // 搜索相关
      searchForm: {
        port: null,
        portAddress: null,
        remake: null,
        portType: null,
        current: 1,
        size: 20,
      },
      createTimes: null,
      // 表格相关
      dataList: [],
      selectionList: [],
      portTypeList: [],
      loading: false,
      tableHeight: undefined,
      total: 0,
      showAddEdit: false,
      showDetial: false,
      type: null,
      addBtn: false,
      viewBtn: false,
      editBtn: false,
      delBtn: false,
    };
  },
  computed: {
    ...mapGetters(["permission", "userDetail"]),
    ...mapState({
      userInfo: state => state.user.userInfo
    }),
    permissionList() {
      return {
        addBtn: this.vaildData(this.permission.endpoint_port_add, false),
        viewBtn: this.vaildData(this.permission.endpoint_port_select, false),
        delBtn: this.vaildData(this.permission.endpoint_port_delete, false),
        editBtn: this.vaildData(this.permission.endpoint_port_update, false)
      };
    },
    ids() {
      let ids = [];
      this.selectionList.forEach(ele => {
        ids.push(ele.id);
      });
      return ids.join(",");
    },
  },
  mounted() {
    // 设置页面元素高度
    this.setPageContentHeight();
    // 设置表格高度
    this.setTableHeight();
    // 初始化查询
    this.onLoad();
    // 初始化字典
    this.getDict();
  },
  methods: {
    // 获得字典
    getDict() {
      getDictList("endpoint_port_type").then(res => {
        this.portTypeList = res.data;
      })
    },
    // 设置表格高度
    setTableHeight() {
      let pageBody = document.getElementsByClassName('page_body');
      this.tableHeight = pageBody[0].offsetHeight - 61 - 47 + 'px';
    },
    handleQuery() {
      this.searchForm.current = 1
      this.onLoad();
    },
    handleDeleteOne(id) {
      //删除按钮
      let ids = id;
      this.handleDeleteConfirm(ids);
      this.selectionList.filter(item => item != id);
    },
    handleDelete() {
      //顶部删除
      if (this.selectionList.length === 0) {
        this.$message.warning("请选择至少一条数据");
        return;
      }
      this.handleDeleteConfirm(this.ids);
    },
    handleDeleteConfirm(ids) {
      this.$confirm("点击确认将永久删除数据且无法恢复，请谨慎选择。", "确定将选择数据删除?", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning"
      })
        .then(() => {
          return remove(ids);
        })
        .then(() => {
          this.onLoad();
          this.$message({
            type: "success",
            message: "操作成功!"
          });
          //重新重新加载已经选择的数据。。。待实现
        });
    },
    searchReset() {
      //重置按钮
      this.searchForm = {
        port: null,
        portAddress: null,
        remake: null,
        current: 1,
        size: 20,
      };
      this.onLoad();
    },
    selectionChange(selection) {
      //点击选择事件
      this.selectionList = selection.map(item => item.id);
    },
    selectionClear() {
      //清除选择
      this.selectionList = [];
      this.$refs.dataTable.clearSelection();
    },
    onLoad() {
      //加载数据
      this.loading = true;
      getList(this.searchForm).then(res => {
        const data = res.data;
        this.total = data.total;
        this.dataList = data.records;
        this.loading = false;
        this.selectionClear();
      });
    },
    handleView(row) {
      //详情 页面
      this.showDetial = true;
      this.fromValue = row;
    },
    handleEdit(row) {
      this.type = 'edit';
      this.showAddEdit = true;
      this.fromValue = row;
    },
  }
};
